def publish(draft: Draft) -> Published:
    if draft is None:
        raise TypeError("draft is required")        # guard: bad input
    if not draft.body:
        raise ValueError("body must not be empty")
    if draft.ready_at > now():
        return draft.defer()                        # guard: recoverable case
    return repo.publish(draft)                      # happy path stays flat
